import React, { useState, useEffect, forwardRef, useMemo } from "react";
import {
    View,
    Text,
    TouchableOpacity,
    ViewProps,
    StyleSheet,
} from "react-native";

import { useTheme } from "@/theme/ThemeProvider";
import type { ThemeTokens } from "@/theme/tokens";

export interface CountdownTimerProps extends ViewProps {
    initialMinutes?: number;
    initialSeconds?: number;
    onResend: () => void;
}

export const CountdownTimer = forwardRef<
    React.ElementRef<typeof View>,
    CountdownTimerProps
>(
    (
        { initialMinutes = 0, initialSeconds = 60, onResend, style, ...props },
        ref,
    ) => {
        const theme = useTheme();
        const styles = useMemo(() => createStyles(theme), [theme]);

        const totalStartingSeconds = initialMinutes * 60 + initialSeconds;
        const [timeLeft, setTimeLeft] = useState(totalStartingSeconds);

        useEffect(() => {
            if (timeLeft <= 0) return;

            const interval = setInterval(() => {
                setTimeLeft((prev) => prev - 1);
            }, 1000);

            return () => clearInterval(interval);
        }, [timeLeft]);

        const handleResendPress = () => {
            setTimeLeft(totalStartingSeconds);
            onResend();
        };

        const formatTime = () => {
            const mins = Math.floor(timeLeft / 60);
            const secs = timeLeft % 60;
            return `${mins.toString().padStart(2, "0")}:${secs.toString().padStart(2, "0")}`;
        };

        return (
            <View ref={ref} style={[styles.container, style]} {...props}>
                <Text style={styles.prefixText}>Resend code in </Text>
                <TouchableOpacity
                    onPress={handleResendPress}
                    disabled={timeLeft > 0}
                >
                    <Text
                        style={[
                            styles.timerText,
                            timeLeft <= 0 && styles.resendText,
                        ]}
                    >
                        {timeLeft > 0 ? formatTime() : "Resend Now"}
                    </Text>
                </TouchableOpacity>
            </View>
        );
    },
);
CountdownTimer.displayName = "CountdownTimer";

const createStyles = (theme: ThemeTokens) =>
    StyleSheet.create({
        container: {
            flexDirection: "row",
            alignItems: "center",
            justifyContent: "center",
        },
        prefixText: {
            fontSize: 14,
            fontWeight: "500",
            color: theme.foregroundMuted,
        },
        timerText: {
            fontSize: 16,
            fontWeight: "700",
            color: theme.primary,
        },
        resendText: {
            fontSize: 14,
        },
    });

import React, { useMemo } from "react";
import { View, StyleSheet, ViewStyle } from "react-native";
import Animated, {
    useAnimatedStyle,
    withTiming,
} from "react-native-reanimated";

import { useTheme } from "@/theme/ThemeProvider";
import type { ThemeTokens } from "@/theme/tokens";

export interface DotSlashPaginationProps {
    data: any[];
    activeIndex: number;
    style?: ViewStyle;
}

export function DotSlashPagination({
    data,
    activeIndex,
    style,
}: DotSlashPaginationProps) {
    const theme = useTheme();
    const styles = useMemo(() => createStyles(theme), [theme]);

    return (
        <View style={[styles.container, style]}>
            {data?.map((_, index) => {
                const isActive = activeIndex === index;

                const animatedStyle = useAnimatedStyle(() => ({
                    width: withTiming(isActive ? 24 : 8, { duration: 300 }),
                }));

                return (
                    <Animated.View
                        key={index}
                        style={[
                            styles.dot,
                            animatedStyle,
                            isActive ? styles.activeDot : styles.inactiveDot,
                        ]}
                    />
                );
            })}
        </View>
    );
}

const createStyles = (theme: ThemeTokens) =>
    StyleSheet.create({
        container: {
            flexDirection: "row",
            alignItems: "center",
            gap: 6,
        },
        dot: {
            height: 8,
            borderRadius: 9999,
        },
        activeDot: {
            backgroundColor: theme.primary,
        },
        inactiveDot: {
            backgroundColor: theme.surfaceMuted, // Fallback for light grey
        },
    });

import React from "react";
import * as LucideIcons from "lucide-react-native";
import { StyleProp, ViewStyle } from "react-native";

export interface DynamicIconProps {
    name: string;
    color?: string;
    size?: number;
    style?: StyleProp<ViewStyle>;
    onPress?: () => void;
}

export function DynamicIcon({
    name,
    color = "#9ca3af",
    size = 20,
    style,
    onPress,
}: DynamicIconProps) {
    const IconComponent = LucideIcons[name as keyof typeof LucideIcons] as any;

    if (!IconComponent) {
        console.warn(`Icon "${name}" does not exist in lucide-react-native.`);
        return null;
    }

    return (
        <IconComponent
            color={color}
            size={size}
            style={style}
            onPress={onPress}
        />
    );
}

import React, { useMemo } from "react";
import { Text, TouchableOpacity, StyleSheet, ViewStyle } from "react-native";

import { HorizontalScroll } from "@/components/layout/horizontal-scroll";

import { useTheme } from "@/theme/ThemeProvider";
import type { ThemeTokens } from "@/theme/tokens";

export interface FilterChipsProps {
    filters: { label: string; value: string }[];
    activeFilter: string;
    onFilterChange: (filter: string) => void;
    style?: ViewStyle;
}

export function FilterChips({
    filters,
    activeFilter,
    onFilterChange,
    style,
}: FilterChipsProps) {
    const theme = useTheme();
    const styles = useMemo(() => createStyles(theme), [theme]);

    return (
        <HorizontalScroll style={style}>
            {filters?.map((filter) => {
                const isActive = activeFilter === filter?.value;
                return (
                    <TouchableOpacity
                        key={filter?.value}
                        onPress={() => onFilterChange(filter?.value)}
                        activeOpacity={0.7}
                        style={[
                            styles.chip,
                            isActive ? styles.chipActive : styles.chipInactive,
                        ]}
                    >
                        <Text
                            style={[
                                styles.text,
                                isActive
                                    ? styles.textActive
                                    : styles.textInactive,
                            ]}
                        >
                            {filter?.label}
                        </Text>
                    </TouchableOpacity>
                );
            })}
        </HorizontalScroll>
    );
}

