import React, { forwardRef, useMemo } from "react";
import {
    View,
    Platform,
    Keyboard,
    KeyboardAvoidingView,
    TouchableWithoutFeedback,
    StyleSheet,
    ViewStyle,
} from "react-native";

import { PageScrollView } from "./page-scrollview";

import { useTheme } from "@/theme/ThemeProvider";
import type { ThemeTokens } from "@/theme/tokens";

export interface KeyboardWrapperProps {
    children: React.ReactNode;
    style?: ViewStyle;
    contentContainerStyle?: ViewStyle;
    keyboardOffset?: number;
    behavior?: "padding" | "height" | "position";
    dismissKeyboardOnTap?: boolean;
    scrollable?: boolean;
}

export const KeyboardWrapper = forwardRef<View, KeyboardWrapperProps>(
    (
        {
            children,
            style,
            contentContainerStyle,
            keyboardOffset = Platform.OS === "ios" ? 10 : 0,
            behavior = Platform.OS === "ios" ? "padding" : undefined,
            dismissKeyboardOnTap = true,
            scrollable = true,
        },
        ref,
    ) => {
        const theme = useTheme();
        const styles = useMemo(() => createStyles(theme), [theme]);

        return (
            <KeyboardAvoidingView
                ref={ref}
                style={[styles.container, style]}
                behavior={behavior}
                keyboardVerticalOffset={keyboardOffset}
            >
                {scrollable ? (
                    <PageScrollView
                        contentContainerStyle={contentContainerStyle}
                        keyboardDismissMode={
                            dismissKeyboardOnTap ? "interactive" : "none"
                        }
                    >
                        {children}
                    </PageScrollView>
                ) : (
                    <TouchableWithoutFeedback
                        onPress={
                            dismissKeyboardOnTap ? Keyboard.dismiss : undefined
                        }
                        accessible={false}
                    >
                        <View style={styles.inner}>{children}</View>
                    </TouchableWithoutFeedback>
                )}
            </KeyboardAvoidingView>
        );
    },
);
KeyboardWrapper.displayName = "KeyboardWrapper";

const createStyles = (theme: ThemeTokens) =>
    StyleSheet.create({
        container: {
            flex: 1,
            backgroundColor: theme.background,
        },
        inner: {
            flex: 1,
        },
    });

import React, { useMemo } from "react";
import { View, ViewProps, StyleSheet } from "react-native";
import { useRouter } from "expo-router";
import { useSafeAreaInsets } from "react-native-safe-area-context";

import { HomeHeader } from "./home-header";
import { NavigatorHeader } from "./navigator-header";

import { useTheme } from "@/theme/ThemeProvider";
import type { ThemeTokens } from "@/theme/tokens";

export interface MainWrapperProps extends ViewProps {
    children: React.ReactNode;
    homeHeader?: boolean;
    navigatorHeader?: boolean;
    heading?: string;
    topSpacing?: boolean;
    style: any;
    fullScreen?: boolean;
    navigatorOptions?: {
        rightBlock?: [{ name?: string; onPress?: () => void; icon?: string }];
    };
}

export function MainWrapper({
    children,
    homeHeader = false,
    navigatorHeader = true,
    heading,
    topSpacing,
    fullScreen = false,
    style,
    navigatorOptions,
    ...props
}: MainWrapperProps) {
    const router = useRouter();
    const insets = useSafeAreaInsets();

    const theme = useTheme();
    const styles = useMemo(() => createStyles(theme), [theme]);

    const safeBottomPadding = Math.min(insets.bottom, 10);

    const handleHomeHeaderRedirects = (route: string) => {
        router.push(route);
    };

    return (
        <View
            style={[
                styles.container,
                {
                    paddingTop: fullScreen
                        ? 0
                        : topSpacing
                          ? insets.top + 30
                          : insets.top + 10,
                    paddingBottom: fullScreen ? 0 : safeBottomPadding,
                },
                style,
            ]}
            {...props}
        >
            <View style={styles.inner}>
                {homeHeader ? (
                    <HomeHeader
                        inMainWrapper
                        title="Zudhan"
                        onItemPress={handleHomeHeaderRedirects}
                    />
                ) : navigatorHeader ? (
                    <NavigatorHeader
                        title={heading ?? ""}
                        inMainWrapper
                        navigatorOptions={navigatorOptions}
                    />
                ) : heading ? (
                    <NavigatorHeader
                        title={heading ?? ""}
                        inMainWrapper
                        haveBackButton={false}
                        navigatorOptions={navigatorOptions}
                    />
                ) : null}

                {children}
            </View>
        </View>
    );
}

const createStyles = (theme: ThemeTokens) =>
    StyleSheet.create({
        container: {
            flex: 1,
            backgroundColor: theme.background,
        },
        inner: {
            flex: 1,
        },
    });

import React, { useMemo } from "react";
import { View, Text, TouchableOpacity, StyleSheet } from "react-native";
import { useRouter } from "expo-router";
import { useSafeAreaInsets } from "react-native-safe-area-context";

import { DynamicIcon } from "@/components/custom/dynamic-icon";

import { useTheme } from "@/theme/ThemeProvider";
import type { ThemeTokens } from "@/theme/tokens";

export interface NavigatorHeaderProps {
    title?: string;
    haveBackButton?: boolean;
    inMainWrapper?: boolean;
    onBackPress?: () => void;
    navigatorOptions?: {
        rightBlock?: [{ name?: string; onPress?: () => void; icon?: string }];
    };
}

export function NavigatorHeader({
    title,
    haveBackButton = true,
    inMainWrapper = true,
    onBackPress,
    style,
    navigatorOptions,
    ...props
}: NavigatorHeaderProps) {
    const router = useRouter();
    const insets = useSafeAreaInsets();

    const theme = useTheme();
    const styles = useMemo(() => createStyles(theme), [theme]);

    const handleBack = () => {
        if (onBackPress) onBackPress();
        else router.back();
    };

    return (
        <View
            style={[
                styles.container,
                { paddingTop: inMainWrapper ? 0 : insets.top + 16 },
                style,
            ]}
            {...props}
        >
            <View style={styles.leftBlock}>
                {haveBackButton && (
                    <TouchableOpacity
                        onPress={handleBack}
                        activeOpacity={0.7}
                        style={styles.backButton}
                    >
                        <DynamicIcon
                            name="ArrowLeft"
                            size={20}
                            color={theme.foreground}
                            className="text-foreground"
                        />
                    </TouchableOpacity>
                )}
            </View>
            <View style={styles.centralBlock}>
                {title && (
                    <Text
                        numberOfLines={1}
                        style={[
                            styles.title,
                            {
                                color: haveBackButton
                                    ? theme.foreground
                                    : theme.primary,
                            },
                        ]}
                    >
                        {title}
                    </Text>
                )}
            </View>
            <View style={styles.rightBlockStyles}>
                {navigatorOptions?.rightBlock?.length &&
                    navigatorOptions?.rightBlock?.map((item, index) => {
                        return (
                            <TouchableOpacity
                                key={index}
                                onPress={item?.onPress}
                                activeOpacity={0.7}
                                style={styles.rightBlockItems}
                            >
                                {item?.name ? (
                                    <DynamicIcon
                                        name={item?.icon as string}
                                        size={20}
                                        color={theme.primary}
                                        className="text-primary"
                                    />
                                ) : item?.name ? (
                                    <Text style={styles.rightBlockNames}>
                                        {item.name}
                                    </Text>
                                ) : null}
                            </TouchableOpacity>
                        );
                    })}
            </View>
        </View>
    );
}

