import React, { useState, forwardRef, useMemo } from "react";
import {
    View,
    Text,
    Modal,
    FlatList,
    Pressable,
    TextInput,
    TouchableOpacity,
    ViewProps,
    StyleSheet,
} from "react-native";

import { DynamicIcon } from "@/components/custom/dynamic-icon";

import { useTheme } from "@/theme/ThemeProvider";
import type { ThemeTokens } from "@/theme/tokens";

import { COUNTRIES, type CountryProps } from "@/constants/data/countries";

export interface PhoneInputProps extends ViewProps {
    value: string;
    onChangeText: (text: string) => void;
    selectedCountry: CountryProps;
    onCountryChange: (country: CountryProps) => void;
    countries?: CountryProps[];
}

export const PhoneInput = forwardRef<
    React.ElementRef<typeof View>,
    PhoneInputProps
>(
    (
        {
            value,
            onChangeText,
            selectedCountry,
            onCountryChange,
            countries = COUNTRIES,
            style,
            ...props
        },
        ref,
    ) => {
        const theme = useTheme();
        const styles = useMemo(() => createStyles(theme), [theme]);

        const [isFocused, setIsFocused] = useState(false);
        const [isPickerVisible, setPickerVisible] = useState(false);

        const handleTextChange = (text: string) => {
            const numericValue = text.replace(/[^0-9]/g, "");
            if (numericValue.length <= selectedCountry.maxLength) {
                onChangeText(numericValue);
            }
        };

        return (
            <View ref={ref} style={[styles.container, style]} {...props}>
                <Text style={styles.label}>Enter your phone number</Text>

                <View
                    style={[
                        styles.inputSurface,
                        isFocused && styles.inputSurfaceFocused,
                    ]}
                >
                    <TouchableOpacity
                        activeOpacity={0.7}
                        onPress={() => setPickerVisible(true)}
                        style={styles.countrySelector}
                    >
                        <Text style={styles.flagText}>
                            {selectedCountry.flag}
                        </Text>
                        <Text style={styles.dialCodeText}>
                            {selectedCountry.dialCode}
                        </Text>
                        <DynamicIcon
                            name="ChevronDown"
                            size={18}
                            color={theme.mutedForeground}
                        />
                    </TouchableOpacity>

                    <View style={styles.divider} />

                    <TextInput
                        value={value}
                        onChangeText={handleTextChange}
                        onFocus={() => setIsFocused(true)}
                        onBlur={() => setIsFocused(false)}
                        keyboardType="number-pad"
                        placeholder="000 000 0000"
                        placeholderTextColor={theme.mutedForeground}
                        style={styles.textInput}
                        maxLength={selectedCountry.maxLength}
                    />
                </View>

                <Modal
                    visible={isPickerVisible}
                    transparent
                    animationType="slide"
                >
                    <Pressable
                        style={styles.modalBackdrop}
                        onPress={() => setPickerVisible(false)}
                    >
                        <View style={styles.modalContent}>
                            <View style={styles.dragIndicatorWrapper}>
                                <View style={styles.dragIndicator} />
                            </View>

                            <Text style={styles.modalTitle}>
                                Select Country
                            </Text>

                            <FlatList
                                data={countries}
                                keyExtractor={(item) => item.id}
                                contentContainerStyle={styles.listContainer}
                                renderItem={({ item }) => (
                                    <TouchableOpacity
                                        activeOpacity={0.7}
                                        onPress={() => {
                                            onCountryChange(item);
                                            setPickerVisible(false);
                                        }}
                                        style={[
                                            styles.listItem,
